def count_defs(code_str: str) -> str:
    import json, re
    # Count function and class definitions using regex
    funcs = len(re.findall(r'^\s*def\s+', code_str, flags=re.MULTILINE))
    classes = len(re.findall(r'^\s*class\s+', code_str, flags=re.MULTILINE))
    return json.dumps({"functions": funcs, "classes": classes})

